// v24.04, HIS ORDER 2026-10-12 (his #45 and his answer 26 b, short voice barks, punchy arcade like CoD and Fortnite): THE ANNOUNCER.
// The big moments were only written: a kill streak, a new high score, two minutes and one minute left, a wave coming in, and the
// extraction. Now an announcer calls them: DOUBLE KILL, TRIPLE KILL, MULTI KILL, RAMPAGE, UNSTOPPABLE, NEW HIGH SCORE, TWO MINUTES,
// ONE MINUTE, WAVE INCOMING, EXTRACTED. Spoken once by the Windows voice and kept in the page like the operator barks, but played full
// band, a shade slower and deeper, on the sting bus (never compressed or ducked) while the room dips under it for a moment. One call
// at a time, apart from the operator barks, so a streak can land over a RELOADING. These are calls, not music (his no raid music).
var VOX_ANN={
  DOUBLEKILL:'',
  TRIPLEKILL:'',
  MULTIKILL:'',
  RAMPAGE:'',
  UNSTOPPABLE:'',
  HISCORE:'',
  EXTRACTED:'',
  TWOMIN:'',
  ONEMIN:'',
  WAVE:''
};
var VOXA={busy:-1,n:0,last:'',dec:0,buf:{}}, VOX_STREAK={'DOUBLE KILL':'DOUBLEKILL','TRIPLE KILL':'TRIPLEKILL','MULTI KILL':'MULTIKILL','RAMPAGE':'RAMPAGE','UNSTOPPABLE':'UNSTOPPABLE'};
function voxCall(k){
  var a, b, t, out, src, hp, g;
  if(!VOX_ANN[k]||(G&&G.sim)) return false;
  if(typeof NET==='object'&&NET&&NET.specTick) return false;
  a=ac(); if(!a) return false;
  if(!VOXA.dec&&a.decodeAudioData){
    VOXA.dec=1;
    Object.keys(VOX_ANN).forEach(function(q){
      try{
        var s=atob(VOX_ANN[q]), u=new Uint8Array(s.length), i, pr;
        for(i=0;i<s.length;i++) u[i]=s.charCodeAt(i);
        pr=a.decodeAudioData(u.buffer,function(x){ if(x&&x.duration) VOXA.buf[q]=x; },function(){});
        if(pr&&pr.then) pr.then(function(x){ if(x&&x.duration) VOXA.buf[q]=x; },function(){});
      }catch(e){}
    });
  }
  b=VOXA.buf[k]; t=a.currentTime;
  if(!b||!b.duration||t<VOXA.busy) return false;
  out=sndBus('sting'); if(!out) return false;
  VOXA.busy=t+b.duration/0.92+0.25; VOXA.n++; VOXA.last=k;
  try{
    src=a.createBufferSource(); src.buffer=b; src.playbackRate.value=0.92;
    hp=a.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=110; hp.Q.value=0.7;
    g=a.createGain(); g.gain.value=0.75;
    src.connect(hp); hp.connect(g); g.connect(out); src.start(t);
    sndDuck('amb',0.6,b.duration); sndDuck('mach',0.75,b.duration);
  }catch(e){ return false; }
  return true;
}
