// v25.xx (noannouncer), HIS ORDER 2026-10-13: "'wave incoming' -- get rid of all spoken sounds like this and just add game sounds instead".
// THE ANNOUNCER IS GONE. v24.04 called the big moments in a recorded voice: a kill streak (DOUBLE KILL to UNSTOPPABLE), NEW HIGH SCORE,
// two minutes and one minute left, a wave coming in and the extraction. Every spoken clip in the page is deleted, with the code that
// decoded and played them. The on-screen callouts stay, and each moment now has a short game sound of its own, built from oscillators
// on the sting bus like the other stingers (never compressed or ducked, the room dips under it for a moment), one at a time:
// a wave coming in is a low urgent alarm, two rising horn pulses; a kill streak is a rising chime ladder, one more note and a higher,
// brighter climb for every level (DOUBLE KILL, TRIPLE KILL, MULTI KILL, RAMPAGE, UNSTOPPABLE); NEW HIGH SCORE is a bright arpeggio
// ending on a held top note; EXTRACTED is a chord that resolves; the two minute mark is a ticking clock and the one minute mark ticks
// faster, climbing, with a low pulse at the end. All of them sit under a gunshot in level. Cosmetic only: no seeded draw, nothing
// under G.sim, no game state.
var ANNC={busy:-1,n:0,last:''}, ANN_STREAK={'DOUBLE KILL':'DOUBLEKILL','TRIPLE KILL':'TRIPLEKILL','MULTI KILL':'MULTIKILL','RAMPAGE':'RAMPAGE','UNSTOPPABLE':'UNSTOPPABLE'};
var ANN_LAD=[523,587,659,784,880,988,1175,1319,1568,1760];
// the notes of one moment: [start s, from Hz, to Hz, seconds, wave, peak level]; len the whole cue; lp a lowpass (0 none)
function annSpec(k){
  var L={DOUBLEKILL:0,TRIPLEKILL:1,MULTIKILL:2,RAMPAGE:3,UNSTOPPABLE:4}[k], N=[], i, f;
  if(L!==undefined){
    for(i=0;i<L+2;i++){ f=ANN_LAD[L+i]; N.push([i*0.075,f,f,0.24,'triangle',0.04]); if(L>0) N.push([i*0.075,f*2,f*2,0.16,'sine',0.006*(L+1)]); }
    return {len:(L+1)*0.075+0.26,lp:0,notes:N};
  }
  if(k==='WAVE') return {len:1.0,lp:850,notes:[[0,110,165,0.4,'sawtooth',0.10],[0.48,147,220,0.4,'sawtooth',0.10]]};
  if(k==='HISCORE'){
    for(i=0;i<6;i++){ f=[523,659,784,1047,1319,1568][i]; N.push([i*0.07,f,f,i===5?0.55:0.2,'triangle',0.06]); N.push([i*0.07,f*2,f*2,i===5?0.4:0.12,'sine',0.014]); }
    return {len:0.95,lp:0,notes:N};
  }
  if(k==='EXTRACTED'){
    [392,523,587].forEach(function(q){ N.push([0,q,q,0.42,'triangle',0.034]); });
    [392,523,659,784].forEach(function(q){ N.push([0.38,q,q,1.0,'triangle',0.03]); });
    N.push([0.38,196,196,1.0,'sine',0.045]);
    return {len:1.45,lp:0,notes:N};
  }
  if(k==='TWOMIN'){ for(i=0;i<4;i++) N.push([i*0.28,(i%2)?1300:1900,(i%2)?1300:1900,0.05,'square',0.04]); return {len:1.0,lp:4200,notes:N}; }
  if(k==='ONEMIN'){ for(i=0;i<6;i++){ f=1500+i*160; N.push([i*0.15,f,f,0.045,'square',0.045]); } N.push([0.9,196,196,0.35,'sawtooth',0.07]); return {len:1.3,lp:4200,notes:N}; }
  return null;
}
function annCue(k){
  var a, sp, t, out, f=null, i, n, o, g;
  if(G&&G.sim) return false;
  if(typeof NET==='object'&&NET&&NET.specTick) return false;
  sp=annSpec(k); if(!sp) return false;
  a=ac(); if(!a) return false;
  t=a.currentTime; if(t<ANNC.busy) return false;
  out=sndBus('sting'); if(!out) return false;
  try{
    if(sp.lp>0){ f=a.createBiquadFilter(); f.type='lowpass'; f.frequency.value=sp.lp; f.Q.value=0.7; f.connect(out); }
    for(i=0;i<sp.notes.length;i++){
      n=sp.notes[i]; o=a.createOscillator(); g=a.createGain(); o.type=n[4];
      o.frequency.setValueAtTime(n[1],t+n[0]); if(n[2]!==n[1]) o.frequency.exponentialRampToValueAtTime(n[2],t+n[0]+n[3]);
      g.gain.setValueAtTime(0.0001,t+n[0]); g.gain.linearRampToValueAtTime(n[5],t+n[0]+0.008); g.gain.exponentialRampToValueAtTime(0.0005,t+n[0]+n[3]);
      o.connect(g); g.connect(f||out); o.start(t+n[0]); o.stop(t+n[0]+n[3]+0.02);
    }
    sndDuck('amb',0.6,sp.len); sndDuck('mach',0.75,sp.len);
  }catch(e){ return false; }
  ANNC.busy=t+sp.len+0.1; ANNC.n++; ANNC.last=k;
  return true;
}
