   finally{
     try{ say=kSay; }catch(_s){}
     try{ fakeOff(); }catch(_f){}
     try{ ANNC.busy=kAnn.busy; ANNC.n=kAnn.n; ANNC.last=kAnn.last; }catch(_k){}
     try{ var g2=__state(); if(g2&&!g2.over) __endRaid('abandon'); }catch(_e){}
